    public boolean isAtSetpoint(ElevatorSubsystem.Setpoint setpoint){
        return getPosition().isNear(setpoint.target, Rotations.of(0.2));
    }

    @Override
    public void periodic() {
        /* refresh all status signals */
        BaseStatusSignal.refreshAll(
            motor_id_35Position,
            motor_id_35Velocity,
            motor_id_35TorqueCurrent
        ); 

        motor_id_35Mech2d.setLength(
            kMinHeight.in(Meters) + motor_id_35Position.getValueAsDouble() * kDrumRadius.in(Meters) * 2 * Math.PI
        );

        DogLog.log("Elevator/DebugLength", motor_id_35Position.getValueAsDouble() * kDrumRadius.in(Meters) * 2 * Math.PI); // temp debug
        DogLog.log("Elevator/rawLengthMeters", elevatorSim_motor_id_35.getPositionMeters());
    }

    private void startSimThread() {
        motor_id_35.getSimState().Orientation = ChassisReference.CounterClockwise_Positive;
        motor_id_35.getSimState().setMotorType(TalonFXSimState.MotorType.KrakenX60);

        lastSimTime = Utils.getCurrentTimeSeconds();

        /* Run simulation at a faster rate so PID gains behave more reasonably */
        simNotifier = new Notifier(() -> {
            /* Calculate the time delta */
            final double currentTime = Utils.getCurrentTimeSeconds();
            final double deltaTime = currentTime - lastSimTime;
            lastSimTime = currentTime;

            final var motor_id_35Sim = motor_id_35.getSimState();

            /* First set the supply voltage of all the devices */
            motor_id_35Sim.setSupplyVoltage(RobotController.getBatteryVoltage());

            /* Then calculate the new position and velocity of the simulated elevator */
            elevatorSim_motor_id_35.setInputVoltage(motor_id_35Sim.getMotorVoltage());
            elevatorSim_motor_id_35.update(deltaTime);

            /* Apply the new rotor position and velocity to the motors (before gear ratio) */
            motor_id_35Sim.setRawRotorPosition(
                Radians.of((elevatorSim_motor_id_35.getPositionMeters() - kMinHeight.in(Meters)) / kDrumRadius.in(Meters) * kGearRatio)
            );
            motor_id_35Sim.setRotorVelocity(
                RadiansPerSecond.of(elevatorSim_motor_id_35.getVelocityMetersPerSecond() / kDrumRadius.in(Meters) * kGearRatio)
            );
        });
        simNotifier.startPeriodic(kSimLoopPeriod);
    }
